#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static int gcm_encrypt(const EVP_CIPHER *cipher,
                       const unsigned char *key, int keylen,
                       const unsigned char *iv, int ivlen,
                       const unsigned char *aad, int aadlen,
                       const unsigned char *pt, int ptlen,
                       unsigned char *out, unsigned char *tag) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen = 0, total = 0, ok = 1;
    if (!ctx) return 0;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) ok = 0;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, ivlen, NULL) != 1) ok = 0;
    if (ok && EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv) != 1) ok = 0;
    if (ok && aad && aadlen) {
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, aad, aadlen) != 1) ok = 0;
    }
    if (ok && EVP_EncryptUpdate(ctx, out, &outlen, pt, ptlen) != 1) ok = 0;
    total = outlen;
    if (ok && EVP_EncryptFinal_ex(ctx, out + total, &outlen) != 1) ok = 0;
    total += outlen;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) != 1) ok = 0;
    EVP_CIPHER_CTX_free(ctx);
    return ok ? total : -1;
}

/* Parallel CTR-like: we cannot easily split GCM without GHASH. Just measure raw AES-GCM. */

int main() {
    const int N = 60000 * 1024;
    unsigned char *pt = malloc(N);
    unsigned char *out = malloc(N + 16);
    unsigned char key[16], iv[12], aad[32], tag[16];
    memset(pt, 0x11, N);
    memset(key, 0x22, 16);
    memset(iv, 0x33, 12);
    memset(aad, 0x44, 32);

    const EVP_CIPHER *cipher = EVP_CIPHER_fetch(NULL, "AES-128-GCM", NULL);
    if (!cipher) { fprintf(stderr, "no cipher\n"); return 1; }

    /* warmup */
    int w = gcm_encrypt(cipher, key, 16, iv, 12, aad, 32, pt, N, out, tag);
    printf("written %d\n", w);

    int reps = 5;
    double t0 = now();
    for (int i = 0; i < reps; i++)
        gcm_encrypt(cipher, key, 16, iv, 12, aad, 32, pt, N, out, tag);
    double t1 = now();
    printf("C EVP AES-128-GCM: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (N/1e6) / ((t1-t0)/reps));

    /* no aad */
    t0 = now();
    for (int i = 0; i < reps; i++)
        gcm_encrypt(cipher, key, 16, iv, 12, NULL, 0, pt, N, out, tag);
    t1 = now();
    printf("C EVP no aad: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (N/1e6) / ((t1-t0)/reps));

    /* reuse ctx */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    t0 = now();
    for (int i = 0; i < reps; i++) {
        int outlen=0, total=0;
        EVP_CIPHER_CTX_reset(ctx);
        EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, out, &outlen, pt, N);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, out+total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("C reuse ctx: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (N/1e6) / ((t1-t0)/reps));

    /* chunk sizes */
    int chunks[] = {65536, 1048576, 4194304, 16777216, N};
    for (int ci = 0; ci < 5; ci++) {
        int chunk = chunks[ci];
        t0 = now();
        for (int i = 0; i < reps; i++) {
            int outlen=0;
            EVP_CIPHER_CTX_reset(ctx);
            EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
            EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
            EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
            int off = 0;
            while (off < N) {
                int n = chunk < (N-off) ? chunk : (N-off);
                EVP_EncryptUpdate(ctx, out+off, &outlen, pt+off, n);
                off += outlen;
            }
            EVP_EncryptFinal_ex(ctx, out+off, &outlen);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
        }
        t1 = now();
        printf("chunk %8d: %.4f s  %.1f MB/s\n", chunk, (t1-t0)/reps, (N/1e6) / ((t1-t0)/reps));
    }

    free(pt); free(out);
    return 0;
}
EOF
