{"command":"cat > build/bw.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

typedef struct {
    unsigned char *src, *dst;
    size_t n;
    int reps;
} job_t;

void *copy_worker(void *arg) {
    job_t *j = arg;
    for (int i = 0; i < j->reps; i++)
        memcpy(j->dst, j->src, j->n);
    return NULL;
}

/* simple write */
void *write_worker(void *arg) {
    job_t *j = arg;
    for (int i = 0; i < j->reps; i++)
        memset(j->dst, i, j->n);
    return NULL;
}

int main() {
    int threads_list[] = {1,2,3,4,6,8,12};
    size_t per = 64 * 1024 * 1024; /* 64MB each */
    int max_t = 12;
    unsigned char **srcs = malloc(max_t * sizeof(void*));
    unsigned char **dsts = malloc(max_t * sizeof(void*));
    for (int i = 0; i < max_t; i++) {
        srcs[i] = malloc(per);
        dsts[i] = malloc(per);
        memset(srcs[i], 1, per);
    }
    printf("allocated %zu MB\n", max_t * 2 * per / (1024*1024));

    for (int ti = 0; ti < 7; ti++) {
        int T = threads_list[ti];
        int reps = 4;
        pthread_t th[16];
        job_t jobs[16];
        double t0 = now();
        for (int i = 0; i < T; i++) {
            jobs[i] = (job_t){srcs[i], dsts[i], per, reps};
            pthread_create(&th[i], NULL, copy_worker, &jobs[i]);
        }
        for (int i = 0; i < T; i++) pthread_join(th[i], NULL);
        double t1 = now();
        double secs = (t1-t0);
        double bytes = (double)T * reps * per * 2; /* R+W */
        printf("memcpy threads=%2d  %.3fs  aggregate %.1f GB/s  per-thread copy %.1f GB/s\n",
               T, secs, bytes/1e9/secs, (double)reps*per/1e9/(secs));
    }
    return 0;
}
EOF
