{"command":"mkdir -p build/gobench && cat > build/gobench/main.go << 'EOF'
package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"fmt"
	"time"
)

func main() {
	N := 60000 * 1024
	key := make([]byte, 16)
	nonce := make([]byte, 12)
	pt := make([]byte, N)
	aad := make([]byte, 32)
	rand.Read(key)
	rand.Read(nonce)
	rand.Read(pt)
	rand.Read(aad)

	block, err := aes.NewCipher(key)
	if err != nil { panic(err) }
	gcm, err := cipher.NewGCM(block)
	if err != nil { panic(err) }

	// warmup
	out := gcm.Seal(nil, nonce, pt, aad)
	fmt.Println("out", len(out))

	reps := 5
	t0 := time.Now()
	for i := 0; i < reps; i++ {
		out = gcm.Seal(out[:0], nonce, pt, aad)
	}
	dt := time.Since(t0)
	fmt.Printf("Go AES-GCM: %.4f s  %.1f MB/s\n", dt.Seconds()/float64(reps), float64(N)/1e6/(dt.Seconds()/float64(reps)))

	// Seal into preallocated
	dst := make([]byte, N+16)
	t0 = time.Now()
	for i := 0; i < reps; i++ {
		gcm.Seal(dst[:0], nonce, pt, aad)
	}
	dt = time.Since(t0)
	fmt.Printf("Go prealloc: %.4f s  %.1f MB/s\n", dt.Seconds()/float64(reps), float64(N)/1e6/(dt.Seconds()/float64(reps)))

	// CTR only
	ctr := cipher.NewCTR(block, append(append([]byte{}, nonce...), 0, 0, 0, 2)) // not quite GCM counter but speed
	// proper 16-byte IV
	iv := make([]byte, 16)
	copy(iv, nonce)
	ctr = cipher.NewCTR(block, iv)
	dst2 := make([]byte, N)
	t0 = time.Now()
	for i := 0; i < reps; i++ {
		ctr.XORKeyStream(dst2, pt)
		// reset by creating new? CTR state advances. recreate
		ctr = cipher.NewCTR(block, iv)
	}
	dt = time.Since(t0)
	fmt.Printf("Go CTR: %.4f s  %.1f MB/s\n", dt.Seconds()/float64(reps), float64(N)/1e6/(dt.Seconds()/float64(reps)))
}
EOF
cd build/gobench && go build -o bench . && ./bench"}

{"command":"cat > build/gobench/par.go << 'EOF'
package main

import (
	"crypto/aes"
	"crypto/cipher"
	"fmt"
	"runtime"
	"sync"
	"time"
)

func main() {
	N := 60000 * 1024
	key := make([]byte, 16)
	for i := range key { key[i] = byte(i) }
	nonce := make([]byte, 12)
	for i := range nonce { nonce[i] = byte(i + 1) }
	pt := make([]byte, N)
	for i := range pt { pt[i] = byte(i) }
	aad := make([]byte, 32)

	block, _ := aes.NewCipher(key)
	gcm, _ := cipher.NewGCM(block)

	// baseline
	out := gcm.Seal(nil, nonce, pt, aad)
	reps := 3
	t0 := time.Now()
	for i := 0; i < reps; i++ {
		out = gcm.Seal(out[:0], nonce, pt, aad)
	}
	dt := time.Since(t0)
	fmt.Printf("serial %.4f s  %.1f MB/s\n", dt.Seconds()/float64(reps), float64(N)/1e6/(dt.Seconds()/float64(reps)))

	// Parallel: split into independent GCM with different nonces just to measure throughput ceiling
	// This is NOT correct GCM, just bandwidth of parallel AES-GCM streams.
	for _, T := range []int{2, 3, 4, 6} {
		runtime.GOMAXPROCS(T)
		chunk := N / T
		// align to 16
		chunk = chunk - chunk%16
		dsts := make([][]byte, T)
		pts := make([][]byte, T)
		nonces := make([][]byte, T)
		for i := 0; i < T; i++ {
			start := i * chunk
			end := start + chunk
			if i == T-1 { end = N }
			pts[i] = pt[start:end]
			dsts[i] = make([]byte, len(pts[i])+16)
			nonces[i] = make([]byte, 12)
			nonces[i][0] = byte(i)
		}
		blocks := make([]cipher.Block, T)
		gcms := make([]cipher.AEAD, T)
		for i := 0; i < T; i++ {
			blocks[i], _ = aes.NewCipher(key)
			gcms[i], _ = cipher.NewGCM(blocks[i])
		}
		// warmup
		var wg sync.WaitGroup
		run := func() {
			wg.Add(T)
			for i := 0; i < T; i++ {
				go func(i int) {
					gcms[i].Seal(dsts[i][:0], nonces[i], pts[i], nil)
					wg.Done()
				}(i)
			}
			wg.Wait()
		}
		run()
		t0 = time.Now()
		for r := 0; r < reps; r++ {
			run()
		}
		dt = time.Since(t0)
		fmt.Printf("parallel T=%d %.4f s  %.1f MB/s\n", T, dt.Seconds()/float64(reps), float64(N)/1e6/(dt.Seconds()/float64(reps)))
	}
	_ = out
}
EOF
