{"command":"cat > build/pgcm.c << 'EOF'
/* Parallel AES-GCM: multi-thread CTR + multi-thread GHASH, then combine.
   Uses OpenSSL AES-NI for block encryption and GHASH via EVP or low-level.
   For speed we use EVP AES-CTR per chunk with correct counter, and
   compute GHASH ourselves with PCLMUL if possible, else OpenSSL.
*/
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

/* Increment 32-bit GCM counter (last 4 bytes, big-endian) by n blocks. */
static void ctr_add(unsigned char counter[16], uint32_t blocks) {
    uint32_t c = ((uint32_t)counter[12] << 24) | ((uint32_t)counter[13] << 16) |
                 ((uint32_t)counter[14] << 8) | counter[15];
    c += blocks;
    counter[12] = c >> 24; counter[13] = c >> 16; counter[14] = c >> 8; counter[15] = c;
}

typedef struct {
    const EVP_CIPHER *cipher;
    unsigned char key[16];
    unsigned char iv[16];
    unsigned char *pt;
    unsigned char *out;
    int len;
} job_t;

static void *ctr_worker(void *arg) {
    job_t *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen = 0;
    EVP_EncryptInit_ex(ctx, j->cipher, NULL, j->key, j->iv);
    EVP_EncryptUpdate(ctx, j->out, &outlen, j->pt, j->len);
    int fin = 0;
    EVP_EncryptFinal_ex(ctx, j->out + outlen, &fin);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main(int argc, char **argv) {
    int T = argc > 1 ? atoi(argv[1]) : 4;
    const int N = 60000 * 1024;
    unsigned char *pt = malloc(N);
    unsigned char *out = malloc(N);
    unsigned char key[16];
    memset(pt, 0x5a, N);
    memset(key, 0x11, 16);

    const EVP_CIPHER *ctr = EVP_CIPHER_fetch(NULL, "AES-128-CTR", NULL);
    if (!ctr) { fprintf(stderr, "no ctr\n"); return 1; }

    /* GCM initial counter is nonce || 0x00000002 for first plaintext block */
    unsigned char base[16];
    memset(base, 0x22, 12);
    base[12] = 0; base[13] = 0; base[14] = 0; base[15] = 2;

    int reps = 4;
    /* warmup */
    {
        int chunk = N / T;
        chunk -= chunk % 16;
        pthread_t th[16];
        job_t jobs[16];
        for (int i = 0; i < T; i++) {
            int start = i * chunk;
            int len = (i == T-1) ? (N - start) : chunk;
            jobs[i].cipher = ctr;
            memcpy(jobs[i].key, key, 16);
            memcpy(jobs[i].iv, base, 16);
            ctr_add(jobs[i].iv, (uint32_t)(start / 16));
            jobs[i].pt = pt + start;
            jobs[i].out = out + start;
            jobs[i].len = len;
        }
        for (int i = 0; i < T; i++) pthread_create(&th[i], NULL, ctr_worker, &jobs[i]);
        for (int i = 0; i < T; i++) pthread_join(th[i], NULL);
    }

    double t0 = now();
    for (int r = 0; r < reps; r++) {
        int chunk = N / T;
        chunk -= chunk % 16;
        pthread_t th[16];
        job_t jobs[16];
        for (int i = 0; i < T; i++) {
            int start = i * chunk;
            int len = (i == T-1) ? (N - start) : chunk;
            jobs[i].cipher = ctr;
            memcpy(jobs[i].key, key, 16);
            memcpy(jobs[i].iv, base, 16);
            ctr_add(jobs[i].iv, (uint32_t)(start / 16));
            jobs[i].pt = pt + start;
            jobs[i].out = out + start;
            jobs[i].len = len;
            pthread_create(&th[i], NULL, ctr_worker, &jobs[i]);
        }
        for (int i = 0; i < T; i++) pthread_join(th[i], NULL);
    }
    double t1 = now();
    printf("parallel CTR T=%d: %.4f s  %.1f MB/s\n", T, (t1-t0)/reps, (N/1e6)/((t1-t0)/reps));

    /* serial CTR for comparison */
    t0 = now();
    for (int r = 0; r < reps; r++) {
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        int outlen = 0;
        EVP_EncryptInit_ex(ctx, ctr, NULL, key, base);
        EVP_EncryptUpdate(ctx, out, &outlen, pt, N);
        EVP_EncryptFinal_ex(ctx, out+outlen, &outlen);
        EVP_CIPHER_CTX_free(ctx);
    }
    t1 = now();
    printf("serial CTR: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (N/1e6)/((t1-t0)/reps));

    free(pt); free(out);
    return 0;
}
EOF
