{"command":"cat > build/aesni_gcm.c << 'EOF'
/* Minimal AES-128-GCM using AES-NI + PCLMULQDQ.
   Measures single-thread and 4-way parallel CTR+GHASH throughput.
*/
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <smmintrin.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static __m128i aes_expand_assist(__m128i t1, __m128i t2) {
    __m128i t3;
    t2 = _mm_shuffle_epi32(t2, 0xff);
    t3 = _mm_slli_si128(t1, 0x4);
    t1 = _mm_xor_si128(t1, t3);
    t3 = _mm_slli_si128(t3, 0x4);
    t1 = _mm_xor_si128(t1, t3);
    t3 = _mm_slli_si128(t3, 0x4);
    t1 = _mm_xor_si128(t1, t3);
    t1 = _mm_xor_si128(t1, t2);
    return t1;
}

static void aes128_key_expand(const uint8_t key[16], __m128i rk[11]) {
    rk[0] = _mm_loadu_si128((const __m128i*)key);
    rk[1] = aes_expand_assist(rk[0], _mm_aeskeygenassist_si128(rk[0], 0x01));
    rk[2] = aes_expand_assist(rk[1], _mm_aeskeygenassist_si128(rk[1], 0x02));
    rk[3] = aes_expand_assist(rk[2], _mm_aeskeygenassist_si128(rk[2], 0x04));
    rk[4] = aes_expand_assist(rk[3], _mm_aeskeygenassist_si128(rk[3], 0x08));
    rk[5] = aes_expand_assist(rk[4], _mm_aeskeygenassist_si128(rk[4], 0x10));
    rk[6] = aes_expand_assist(rk[5], _mm_aeskeygenassist_si128(rk[5], 0x20));
    rk[7] = aes_expand_assist(rk[6], _mm_aeskeygenassist_si128(rk[6], 0x40));
    rk[8] = aes_expand_assist(rk[7], _mm_aeskeygenassist_si128(rk[7], 0x80));
