/* 8-block parallel CTR */
static void aes_ctr_8(const __m128i rk[11], uint8_t counter[16], const uint8_t *in, uint8_t *out, size_t nblocks) {
    uint32_t ctr = ((uint32_t)counter[12]<<24)|((uint32_t)counter[13]<<16)|((uint32_t)counter[14]<<8)|counter[15];
    uint8_t prefix[12];
    memcpy(prefix, counter, 12);
    size_t i = 0;
    while (i + 8 <= nblocks) {
        __m128i b[8];
        for (int k = 0; k < 8; k++) {
            uint8_t c[16];
            memcpy(c, prefix, 12);
            uint32_t v = ctr + (uint32_t)(i + k);
            c[12]=v>>24; c[13]=v>>16; c[14]=v>>8; c[15]=v;
            b[k] = _mm_loadu_si128((const __m128i*)c);
            b[k] = _mm_xor_si128(b[k], rk[0]);
        }
        for (int r = 1; r < 10; r++) {
            for (int k = 0; k < 8; k++) b[k] = _mm_aesenc_si128(b[k], rk[r]);
        }
        for (int k = 0; k < 8; k++) b[k] = _mm_aesenclast_si128(b[k], rk[10]);
        for (int k = 0; k < 8; k++) {
            __m128i p = _mm_loadu_si128((const __m128i*)(in + (i+k)*16));
            b[k] = _mm_xor_si128(b[k], p);
            _mm_storeu_si128((__m128i*)(out + (i+k)*16), b[k]);
        }
        i += 8;
    }
    while (i < nblocks) {
        uint8_t c[16];
        memcpy(c, prefix, 12);
        uint32_t v = ctr + (uint32_t)i;
        c[12]=v>>24; c[13]=v>>16; c[14]=v>>8; c[15]=v;
        __m128i b = aes128_encrypt_block(_mm_loadu_si128((const __m128i*)c), rk);
        __m128i p = _mm_loadu_si128((const __m128i*)(in + i*16));
        _mm_storeu_si128((__m128i*)(out + i*16), _mm_xor_si128(b, p));
        i++;
    }
}

typedef struct {
    __m128i rk[11];
    uint8_t counter[16];
    const uint8_t *in;
    uint8_t *out;
    size_t nblocks;
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    aes_ctr_8(j->rk, j->counter, j->in, j->out, j->nblocks);
    return NULL;
}

int main(int argc, char **argv) {
    int T = argc > 1 ? atoi(argv[1]) : 1;
    const size_t N = 60000ull * 1024;
    const size_t nblocks = N / 16;
    uint8_t *pt = aligned_alloc(64, N);
    uint8_t *out = aligned_alloc(64, N);
    memset(pt, 0x5a, N);
    uint8_t key[16];
    memset(key, 0x11, 16);
    __m128i rk[11];
    aes128_key_expand(key, rk);

    uint8_t counter[16];
    memset(counter, 0x22, 12);
    counter[12]=0; counter[13]=0; counter[14]=0; counter[15]=2;

    int reps = 4;
    if (T == 1) {
        /* warmup */
        aes_ctr_8(rk, counter, pt, out, nblocks);
        double t0 = now();
        for (int r = 0; r < reps; r++)
            aes_ctr_8(rk, counter, pt, out, nblocks);
        double t1 = now();
        printf("serial AES-NI CTR: %.4f s  %.1f MB/s\n", (t1-t0)/reps, (N/1e6)/((t1-t0)/reps));
    } else {
        size_t chunk = nblocks / T;
        chunk -= chunk % 8;
        job_t jobs[16];
        pthread_t th[16];
        for (int i = 0; i < T; i++) {
            memcpy(jobs[i].rk, rk, sizeof(rk));
            memcpy(jobs[i].counter, counter, 16);
            uint32_t add = (uint32_t)(i * chunk);
            uint32_t c = 2 + add;
            jobs[i].counter[12]=c>>24; jobs[i].counter[13]=c>>16; jobs[i].counter[14]=c>>8; jobs[i].counter[15]=c;
            jobs[i].in = pt + i * chunk * 16;
            jobs[i].out = out + i * chunk * 16;
            jobs[i].nblocks = (i == T-1) ? (nblocks - i*chunk) : chunk;
        }
        /* warmup */
        for (int i = 0; i < T; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
        for (int i = 0; i < T; i++) pthread_join(th[i], NULL);
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            for (int i = 0; i < T; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
            for (int i = 0; i < T; i++) pthread_join(th[i], NULL);
        }
        double t1 = now();
        printf("parallel T=%d AES-NI CTR: %.4f s  %.1f MB/s\n", T, (t1-t0)/reps, (N/1e6)/((t1-t0)/reps));
    }
    free(pt); free(out);
    return 0;
}
