static inline __m128i aes_block(const __m128i rk[11], __m128i b) {
    b = _mm_xor_si128(b, rk[0]);
    b = _mm_aesenc_si128(b, rk[1]);
    b = _mm_aesenc_si128(b, rk[2]);
    b = _mm_aesenc_si128(b, rk[3]);
    b = _mm_aesenc_si128(b, rk[4]);
    b = _mm_aesenc_si128(b, rk[5]);
    b = _mm_aesenc_si128(b, rk[6]);
    b = _mm_aesenc_si128(b, rk[7]);
    b = _mm_aesenc_si128(b, rk[8]);
    b = _mm_aesenc_si128(b, rk[9]);
    return _mm_aesenclast_si128(b, rk[10]);
}

/* GHASH multiply, reflected, from Intel PCLMULQDQ paper (Gueron/Kounavis). */
static inline __m128i gfmul(__m128i a, __m128i b) {
    __m128i tmp0, tmp1, tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9;
    tmp0 = _mm_clmulepi64_si128(a, b, 0x00);
    tmp1 = _mm_clmulepi64_si128(a, b, 0x11);
    tmp2 = _mm_shuffle_epi32(a, 78);
    tmp3 = _mm_shuffle_epi32(b, 78);
    tmp2 = _mm_xor_si128(tmp2, a);
    tmp3 = _mm_xor_si128(tmp3, b);
    tmp2 = _mm_clmulepi64_si128(tmp2, tmp3, 0x00);
    tmp2 = _mm_xor_si128(tmp2, tmp0);
    tmp2 = _mm_xor_si128(tmp2, tmp1);
    tmp3 = _mm_slli_si128(tmp2, 8);
    tmp4 = _mm_srli_si128(tmp2, 8);
    tmp0 = _mm_xor_si128(tmp0, tmp3);
    tmp1 = _mm_xor_si128(tmp1, tmp4);

    tmp5 = _mm_srli_epi32(tmp0, 31);
    tmp6 = _mm_srli_epi32(tmp0, 30);
    tmp7 = _mm_srli_epi32(tmp0, 25);
    tmp5 = _mm_xor_si128(tmp5, tmp6);
    tmp5 = _mm_xor_si128(tmp5, tmp7);
    tmp6 = _mm_slli_si128(tmp5, 4);          /* << 32 */
    tmp7 = _mm_srli_si128(tmp5, 12);         /* >> 96 */
    tmp0 = _mm_xor_si128(tmp0, tmp6);
    tmp1 = _mm_xor_si128(tmp1, tmp7);

    tmp8 = _mm_slli_epi32(tmp0, 1);
    tmp9 = _mm_slli_epi32(tmp0, 2);
    tmp5 = _mm_slli_epi32(tmp0, 7);
    tmp8 = _mm_xor_si128(tmp8, tmp9);
    tmp8 = _mm_xor_si128(tmp8, tmp5);
    tmp0 = _mm_xor_si128(tmp0, tmp8);
    tmp0 = _mm_xor_si128(tmp0, tmp1);
    return tmp0;
}

static __m128i ghash(const uint8_t *data, size_t len, __m128i H, __m128i bswap) {
    __m128i y = _mm_setzero_si128();
    size_t n = len / 16;
    for (size_t i = 0; i < n; i++) {
        __m128i x = _mm_loadu_si128((const __m128i*)(data + i*16));
        x = _mm_shuffle_epi8(x, bswap);
        y = gfmul(_mm_xor_si128(y, x), H);
    }
    if (len & 15) {
        uint8_t last[16] = {0};
        memcpy(last, data + n*16, len & 15);
        __m128i x = _mm_loadu_si128((const __m128i*)last);
        x = _mm_shuffle_epi8(x, bswap);
        y = gfmul(_mm_xor_si128(y, x), H);
    }
    return y;
}

static void ctr_xor(const __m128i rk[11], __m128i counter_le, const uint8_t *in, uint8_t *out, size_t nblocks) {
    __m128i bswap = _mm_loadu_si128((const __m128i*)BSWAP_BYTES);
    __m128i one = _mm_set_epi32(0,0,0,1);
    __m128i eight = _mm_set_epi32(0,0,0,8);
    size_t i = 0;
    while (i + 8 <= nblocks) {
        __m128i c = counter_le;
        __m128i b0 = _mm_xor_si128(_mm_shuffle_epi8(c, bswap), rk[0]); c = _mm_add_epi32(c, one);
        __m128i b1 = _mm_xor_si128(_mm_shuffle_epi8(c, bswap), rk[0]); c = _mm_add_epi32(c, one);
        __m128i b2 = _mm_xor_si128(_mm_shuffle_epi8(c, bswap), rk[0]); c = _mm_add_epi32(c, one);
        __m128i b3 = _mm_xor_si128(_mm_shuffle_epi8(c, bswap), rk[0]); c = _mm_add_epi32(c, one);
        __m128i b4 = _mm_xor_si128(_mm_shuffle_epi8(c, bswap), rk[0]); c = _mm_add_epi32(c, one);
        __m128i b5 = _mm_xor_si128(_mm_shuffle_epi8(c, bswap), rk[0]); c = _mm_add_epi32(c, one);
        __m128i b6 = _mm_xor_si128(_mm_shuffle_epi8(c, bswap), rk[0]); c = _mm_add_epi32(c, one);
        __m128i b7 = _mm_xor_si128(_mm_shuffle_epi8(c, bswap), rk[0]);
        #define R(rr) \
            b0=_mm_aesenc_si128(b0,rk[rr]); b1=_mm_aesenc_si128(b1,rk[rr]); \
            b2=_mm_aesenc_si128(b2,rk[rr]); b3=_mm_aesenc_si128(b3,rk[rr]); \
            b4=_mm_aesenc_si128(b4,rk[rr]); b5=_mm_aesenc_si128(b5,rk[rr]); \
            b6=_mm_aesenc_si128(b6,rk[rr]); b7=_mm_aesenc_si128(b7,rk[rr]);
        R(1) R(2) R(3) R(4) R(5) R(6) R(7) R(8) R(9)
        #undef R
        b0=_mm_aesenclast_si128(b0,rk[10]); b1=_mm_aesenclast_si128(b1,rk[10]);
        b2=_mm_aesenclast_si128(b2,rk[10]); b3=_mm_aesenclast_si128(b3,rk[10]);
        b4=_mm_aesenclast_si128(b4,rk[10]); b5=_mm_aesenclast_si128(b5,rk[10]);
        b6=_mm_aesenclast_si128(b6,rk[10]); b7=_mm_aesenclast_si128(b7,rk[10]);
        _mm_storeu_si128((__m128i*)(out+i*16+0),   _mm_xor_si128(b0, _mm_loadu_si128((const __m128i*)(in+i*16+0))));
        _mm_storeu_si128((__m128i*)(out+i*16+16),  _mm_xor_si128(b1, _mm_loadu_si128((const __m128i*)(in+i*16+16))));
        _mm_storeu_si128((__m128i*)(out+i*16+32),  _mm_xor_si128(b2, _mm_loadu_si128((const __m128i*)(in+i*16+32))));
        _mm_storeu_si128((__m128i*)(out+i*16+48),  _mm_xor_si128(b3, _mm_loadu_si128((const __m128i*)(in+i*16+48))));
        _mm_storeu_si128((__m128i*)(out+i*16+64),  _mm_xor_si128(b4, _mm_loadu_si128((const __m128i*)(in+i*16+64))));
        _mm_storeu_si128((__m128i*)(out+i*16+80),  _mm_xor_si128(b5, _mm_loadu_si128((const __m128i*)(in+i*16+80))));
        _mm_storeu_si128((__m128i*)(out+i*16+96),  _mm_xor_si128(b6, _mm_loadu_si128((const __m128i*)(in+i*16+96))));
        _mm_storeu_si128((__m128i*)(out+i*16+112), _mm_xor_si128(b7, _mm_loadu_si128((const __m128i*)(in+i*16+112))));
        counter_le = _mm_add_epi32(counter_le, eight);
        i += 8;
    }
    while (i < nblocks) {
        __m128i b = aes_block(rk, _mm_shuffle_epi8(counter_le, bswap));
        __m128i p = _mm_loadu_si128((const __m128i*)(in + i*16));
        _mm_storeu_si128((__m128i*)(out + i*16), _mm_xor_si128(b, p));
        counter_le = _mm_add_epi32(counter_le, one);
        i++;
    }
}

typedef struct {
    __m128i rk[11];
    __m128i counter_le;
    const uint8_t *in;
    uint8_t *out;
    size_t nblocks;
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    ctr_xor(j->rk, j->counter_le, j->in, j->out, j->nblocks);
    return NULL;
}

static __m128i load_counter_le(const uint8_t mem[16]) {
    __m128i bswap = _mm_loadu_si128((const __m128i*)BSWAP_BYTES);
    return _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)mem), bswap);
}

/* nonce must be 12 bytes. ptlen may be any size. threads >= 1. */
int gcm128_encrypt(const uint8_t key[16], const uint8_t nonce[12],
                   const uint8_t *aad, int aadlen,
                   const uint8_t *pt, int ptlen,
                   uint8_t *ct, uint8_t tag[16], int threads) {
    __m128i rk[11];
    expand128(key, rk);
    __m128i bswap = _mm_loadu_si128((const __m128i*)BSWAP_BYTES);

    /* H = AES(0) byte-swapped for reflected GHASH */
    __m128i H = aes_block(rk, _mm_setzero_si128());
    H = _mm_shuffle_epi8(H, bswap);

    /* J0 = nonce || 0x00000001 */
    uint8_t j0[16];
    memcpy(j0, nonce, 12);
    j0[12]=0; j0[13]=0; j0[14]=0; j0[15]=1;
    __m128i EK0 = aes_block(rk, _mm_loadu_si128((const __m128i*)j0));

    /* CTR starts at inc32(J0) = nonce || 0x00000002 */
    uint8_t ctr0[16];
    memcpy(ctr0, nonce, 12);
    ctr0[12]=0; ctr0[13]=0; ctr0[14]=0; ctr0[15]=2;

    size_t nfull = (size_t)ptlen / 16;
    size_t rem = (size_t)ptlen % 16;

    if (threads < 1) threads = 1;
    if (threads > 8) threads = 8;
    if ((int)nfull < threads * 16) threads = 1;

    if (threads == 1) {
        ctr_xor(rk, load_counter_le(ctr0), pt, ct, nfull);
    } else {
        size_t chunk = (nfull / threads) & ~7ull;
        if (chunk == 0) {
            ctr_xor(rk, load_counter_le(ctr0), pt, ct, nfull);
        } else {
            pthread_t th[8];
            job_t jobs[8];
            int launched = 0;
            size_t done = 0;
            for (int i = 0; i < threads; i++) {
                size_t blocks = (i == threads-1) ? (nfull - done) : chunk;
                if (blocks == 0) break;
                memcpy(jobs[i].rk, rk, sizeof(rk));
                uint8_t c[16];
                memcpy(c, ctr0, 16);
                uint32_t v = 2u + (uint32_t)done;
                c[12]=v>>24; c[13]=v>>16; c[14]=v>>8; c[15]=v;
                jobs[i].counter_le = load_counter_le(c);
                jobs[i].in = pt + done*16;
                jobs[i].out = ct + done*16;
                jobs[i].nblocks = blocks;
                pthread_create(&th[i], NULL, worker, &jobs[i]);
                launched++;
                done += blocks;
            }
            for (int i = 0; i < launched; i++) pthread_join(th[i], NULL);
        }
    }
    if (rem) {
        uint8_t c[16];
        memcpy(c, ctr0, 16);
        uint32_t v = 2u + (uint32_t)nfull;
        c[12]=v>>24; c[13]=v>>16; c[14]=v>>8; c[15]=v;
        __m128i ks = aes_block(rk, _mm_loadu_si128((const __m128i*)c));
        uint8_t ksb[16];
        _mm_storeu_si128((__m128i*)ksb, ks);
        for (size_t i = 0; i < rem; i++) ct[nfull*16 + i] = pt[nfull*16 + i] ^ ksb[i];
    }

    /* GHASH over AAD then ciphertext */
    __m128i y = _mm_setzero_si128();
    if (aad && aadlen > 0) {
        y = ghash(aad, (size_t)aadlen, H, bswap);
    }
    /* continue GHASH over ct: ghash() starts from 0, so fold manually */
    {
        size_t len = (size_t)ptlen;
        size_t n = len / 16;
        for (size_t i = 0; i < n; i++) {
            __m128i x = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(ct + i*16)), bswap);
            y = gfmul(_mm_xor_si128(y, x), H);
        }
        if (len & 15) {
            uint8_t last[16] = {0};
            memcpy(last, ct + n*16, len & 15);
            __m128i x = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)last), bswap);
            y = gfmul(_mm_xor_si128(y, x), H);
        }
    }
    /* lengths block: [aadlen*8][ptlen*8] as 64-bit big-endian */
    uint8_t lenb[16] = {0};
    uint64_t al = (uint64_t)aadlen * 8;
    uint64_t cl = (uint64_t)ptlen * 8;
    for (int i = 0; i < 8; i++) {
        lenb[7-i] = (uint8_t)(al >> (8*i));
        lenb[15-i] = (uint8_t)(cl >> (8*i));
    }
    __m128i L = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)lenb), bswap);
    y = gfmul(_mm_xor_si128(y, L), H);
    y = _mm_shuffle_epi8(y, bswap);
    __m128i T = _mm_xor_si128(y, EK0);
    _mm_storeu_si128((__m128i*)tag, T);
    return 0;
}

/* self-test main */
#ifdef TEST_MAIN
#include <stdio.h>
#include <time.h>
int main() {
    const size_t N = 60000ull * 1024;
    uint8_t *pt = malloc(N);
    uint8_t *ct = malloc(N);
    uint8_t key[16], nonce[12], aad[32], tag[16];
    memset(pt, 0x11, N);
    memset(key, 0x22, 16);
    memset(nonce, 0x33, 12);
    memset(aad, 0x44, 32);
    gcm128_encrypt(key, nonce, aad, 32, pt, (int)N, ct, tag, 1);
    struct timespec ts;
    int reps = 3;
    for (int T = 1; T <= 6; T++) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double t0 = ts.tv_sec + ts.tv_nsec*1e-9;
        for (int r = 0; r < reps; r++)
            gcm128_encrypt(key, nonce, aad, 32, pt, (int)N, ct, tag, T);
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double t1 = ts.tv_sec + ts.tv_nsec*1e-9;
        printf("T=%d %.4f s  %.1f MB/s  tag=%02x%02x\n", T, (t1-t0)/reps, (N/1e6)/((t1-t0)/reps), tag[0], tag[1]);
    }
    free(pt); free(ct);
    return 0;
}
#endif
EOF
clang -O3 -maes -mpclmul -mssse3 -msse4.1 -DTEST_MAIN -o build/fastgcm build/fastgcm.c -lpthread && ./build/fastgcm"}

