static unsigned __int128 gf_mul(unsigned __int128 x, unsigned __int128 y) {
    unsigned __int128 z = 0;
    unsigned __int128 v = y;
    const unsigned __int128 R = (unsigned __int128)0xe1 << 120;
    for (int i = 0; i < 128; i++) {
        if ((x >> (127-i)) & 1) z ^= v;
        if (v & 1) v = (v >> 1) ^ R;
