    t7 = _mm_slli_epi64(t0, 7);
    t5 = _mm_xor_si128(t5, t6);
    t5 = _mm_xor_si128(t5, t7);
    t0 = _mm_xor_si128(t0, t5);
    t0 = _mm_xor_si128(t0, t1);
