}

/* Also: implement reduction in NIST bit order using 64-bit clmul pieces
   and a software-style fold, to guarantee correctness, then optimize.

   x * y in GF(2^128) NIST:
   Let the 256-bit product be Z (bit 0 = x^255 term? NIST MSB is x^127).
   Easier to use the reflected form correctly.

   I'll compute product with clmul on bit-reversed operands (so clmul's
   low bit = NIST high bit), then reduce using the reflected polynomial
   x^128 + x^7 + x^2 + x + 1, which is what mul_intel_reflected does,
   then bit-reverse the result back to NIST order.
*/

int main() {
    uint8_t Hb[16] = {0xc6,0xa1,0x3b,0x37,0x87,0x8f,0x5b,0x82,0x6f,0x4f,0x81,0x62,0xa1,0xc8,0xd8,0x79};
    uint8_t Xb[16]; for (int i=0;i<16;i++) Xb[i]=i;
    printf("expect               0dee47360a9b69d99ab5d81654439e03\n");
    __m128i H = _mm_loadu_si128((const __m128i*)Hb);
    __m128i X = _mm_loadu_si128((const __m128i*)Xb);

    __m128i Hr = bitrev128(H);
    __m128i Xr = bitrev128(X);
    __m128i Yr = mul_intel_reflected(Xr, Hr);
    phex("bitrev roundtrip", bitrev128(Yr));
    phex("no final bitrev", Yr);
    phex("bswap only round", bswap(mul_intel_reflected(bswap(X), bswap(H))));

    /* speed of bitrev mul on 60MB */
    const size_t N = 60000ull*1024;
    uint8_t *data = malloc(N);
    memset(data, 0xab, N);
    size_t nb = N/16;
    __m128i acc = _mm_setzero_si128();
    /* warmup */
    for (size_t i = 0; i < 1024; i++) {
        __m128i x = bitrev128(_mm_loadu_si128((const __m128i*)(data+i*16)));
        acc = mul_intel_reflected(_mm_xor_si128(acc, x), Hr);
    }
    double t0 = now();
    acc = _mm_setzero_si128();
    for (size_t i = 0; i < nb; i++) {
        __m128i x = bitrev128(_mm_loadu_si128((const __m128i*)(data+i*16)));
        acc = mul_intel_reflected(_mm_xor_si128(acc, x), Hr);
    }
    double t1 = now();
    printf("ghash bitrev %.4f s  %.1f MB/s\n", t1-t0, (N/1e6)/(t1-t0));
    phex("acc", bitrev128(acc));
    free(data);
    return 0;
}
