    __m128i L = _mm_loadu_si128((const __m128i*)lut);
    lo = _mm_shuffle_epi8(L, lo);
    hi = _mm_shuffle_epi8(L, hi);
    return _mm_or_si128(_mm_slli_epi16(lo, 4), hi);
}
static inline __m128i bitrev128(__m128i x) { return byte_rev_bits(bswap(x)); }

/* Multiply two bit-reversed GHASH elements. Result is bit-reversed. */
static inline __m128i gfmul_reflected(__m128i a, __m128i b) {
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z1 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i z2 = _mm_clmulepi64_si128(a, b, 0x01);
    __m128i z3 = _mm_clmulepi64_si128(a, b, 0x10);
    z2 = _mm_xor_si128(z2, z3);
    /* 256-bit product: lo = z0 xor (z2 << 64), hi = z1 xor (z2 >> 64) */
    __m128i lo = _mm_xor_si128(z0, _mm_slli_si128(z2, 8));
    __m128i hi = _mm_xor_si128(z1, _mm_srli_si128(z2, 8));

    /* r = lo xor hi xor (hi<<1) xor (hi<<2) xor (hi<<7), then fold overflow.
       Shifts are on the 128-bit value (not per-lane). */
    __m128i hi1 = _mm_or_si128(_mm_slli_epi64(hi, 1), _mm_srli_epi64(_mm_slli_si128(hi, 8), 63));
    __m128i hi2 = _mm_or_si128(_mm_slli_epi64(hi, 2), _mm_srli_epi64(_mm_slli_si128(hi, 8), 62));
    __m128i hi7 = _mm_or_si128(_mm_slli_epi64(hi, 7), _mm_srli_epi64(_mm_slli_si128(hi, 8), 57));
    __m128i r = _mm_xor_si128(lo, hi);
    r = _mm_xor_si128(r, hi1);
    r = _mm_xor_si128(r, hi2);
    r = _mm_xor_si128(r, hi7);

    /* overflow bits: the bits shifted out of the top of hi by <<1, <<2, <<7.
       hi<<1 overflows 1 bit, hi<<2 overflows 2, hi<<7 overflows 7.
       Those bits land in a small integer we fold with poly 0x87.
       Extract top byte-ish: bits 127..121 of hi are the ones that can overflow <<7.
    */
    uint64_t hi_top = (uint64_t)_mm_extract_epi64(hi, 1); /* high 64 of hi, but we need bits 127-121 which are the top of high 64 */
    /* bits shifted out:
       <<1: bit 127
       <<2: bits 127,126
       <<7: bits 127..121
       over = (hi>>127) xor (hi>>126) xor (hi>>121)   as a small value in the low bits? 
       Let's compute over as a 16-bit value from the top of hi.
    */
    uint32_t top = (uint32_t)(hi_top >> 48); /* bits 112..127 of the 128-bit hi, in the low 16 of top? 
       hi_top bit 63 = bit 127 of hi.
       hi_top >> (63-k) gives bit (127-k) into bit 0? Let's be explicit. */
    unsigned over = 0;
    /* bit i of hi (i=121..127) contributes to over bit (i+s-128) for s in {0,1,2,7} if i+s>=128.
       s=0 doesn't overflow. */
    uint32_t hibits = (uint32_t)(hi_top >> 57); /* bits 121..127 in low 7 bits, bit0 = bit121 */
    /* <<1 overflow: bit 127 -> over bit 0. bit127 is hibits bit 6 */
    /* <<2 overflow: bit 126 -> over bit 0, bit 127 -> over bit 1 */
    /* <<7 overflow: bit 121 -> over bit 0, ..., bit 127 -> over bit 6 */
    over = (hibits >> 6)                 /* <<1, bit127 -> bit0 */
          ^ (hibits >> 5)                /* <<2, bit126 -> bit0, bit127 -> bit1 */
          ^ hibits;                      /* <<7, bit121 -> bit0 ... */
    /* over is at most 7 bits. Fold: r ^= over ^ (over<<1) ^ (over<<2) ^ (over<<7) */
    unsigned fold = over ^ (over << 1) ^ (over << 2) ^ (over << 7);
    /* second overflow of fold (over<<7 can set bits 7..13, no second overflow past bit 7 of a 7-bit over? 
       over is 7 bits, over<<7 is bits 7..13, none past 127. So no second reduction needed if we only
       xor into the low 14 bits. Good. */
    __m128i f = _mm_cvtsi32_si128((int)fold);
    r = _mm_xor_si128(r, f);
    return r;
}

static void phex(const char *n, __m128i v) {
    uint8_t b[16]; _mm_storeu_si128((__m128i*)b, v);
    printf("%-16s ", n); for (int i=0;i<16;i++) printf("%02x", b[i]); printf("\n");
}

int main() {
    uint8_t Hb[16] = {0xc6,0xa1,0x3b,0x37,0x87,0x8f,0x5b,0x82,0x6f,0x4f,0x81,0x62,0xa1,0xc8,0xd8,0x79};
    uint8_t Xb[16]; for (int i=0;i<16;i++) Xb[i]=i;
    printf("expect           0dee47360a9b69d99ab5d81654439e03\n");
    __m128i H = _mm_loadu_si128((const __m128i*)Hb);
    __m128i X = _mm_loadu_si128((const __m128i*)Xb);
    __m128i Hr = bitrev128(H);
    __m128i Xr = bitrev128(X);
    __m128i Yr = gfmul_reflected(Xr, Hr);
    phex("result nist", bitrev128(Yr));
    phex("result raw", Yr);

    /* speed */
    const size_t N = 60000ull * 1024;
    uint8_t *data = malloc(N);
    memset(data, 0x5a, N);
    size_t nb = N/16;
    __m128i acc = _mm_setzero_si128();
    double t0 = now();
    for (size_t i = 0; i < nb; i++) {
        __m128i x = bitrev128(_mm_loadu_si128((const __m128i*)(data + i*16)));
        acc = gfmul_reflected(_mm_xor_si128(acc, x), Hr);
    }
    double t1 = now();
