static inline __m128i byte_rev_bits(__m128i x) {
    __m128i m1 = _mm_set1_epi8(0x0f);
    __m128i lo = _mm_and_si128(x, m1);
    __m128i hi = _mm_and_si128(_mm_srli_epi16(x, 4), m1);
    const uint8_t lut[16] = {0x0,0x8,0x4,0xc,0x2,0xa,0x6,0xe,0x1,0x9,0x5,0xd,0x3,0xb,0x7,0xf};
    __m128i L = _mm_loadu_si128((const __m128i*)lut);
    lo = _mm_shuffle_epi8(L, lo);
    hi = _mm_shuffle_epi8(L, hi);
    return _mm_or_si128(_mm_slli_epi16(lo, 4), hi);
}
static inline __m128i bitrev128(__m128i x) { return byte_rev_bits(bswap(x)); }

static inline __m128i shl128(__m128i x, int n) {
    /* shift left by n bits (n < 64) */
    __m128i left = _mm_slli_epi64(x, n);
    __m128i carry = _mm_srli_epi64(x, 64 - n);
    carry = _mm_slli_si128(carry, 8); /* move low-lane carry into high lane */
    return _mm_or_si128(left, carry);
}
static inline __m128i shr128(__m128i x, int n) {
    __m128i right = _mm_srli_epi64(x, n);
    __m128i carry = _mm_slli_epi64(x, 64 - n);
    carry = _mm_srli_si128(carry, 8);
    return _mm_or_si128(right, carry);
}

static inline __m128i gfmul(__m128i a, __m128i b) {
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z1 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i z2 = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01),
                               _mm_clmulepi64_si128(a, b, 0x10));
    __m128i lo = _mm_xor_si128(z0, _mm_slli_si128(z2, 8));
    __m128i hi = _mm_xor_si128(z1, _mm_srli_si128(z2, 8));

    __m128i r = lo;
    r = _mm_xor_si128(r, hi);
    r = _mm_xor_si128(r, shl128(hi, 1));
    r = _mm_xor_si128(r, shl128(hi, 2));
    r = _mm_xor_si128(r, shl128(hi, 7));

    /* overflow of those shifts: bits that left the top */
    __m128i over = shr128(hi, 127);          /* <<1 overflow */
    over = _mm_xor_si128(over, shr128(hi, 126));
    over = _mm_xor_si128(over, shr128(hi, 121));
    /* over is a few low bits. fold */
    __m128i fold = over;
    fold = _mm_xor_si128(fold, shl128(over, 1));
    fold = _mm_xor_si128(fold, shl128(over, 2));
    fold = _mm_xor_si128(fold, shl128(over, 7));
    /* over<<7 could overflow again (over has up to 7 bits, <<7 -> bits 7..13, no overflow past 127). */
    r = _mm_xor_si128(r, fold);
    return r;
}

static void phex(const char *n, __m128i v) {
    uint8_t b[16]; _mm_storeu_si128((__m128i*)b, v);
    printf("%-12s ", n); for (int i=0;i<16;i++) printf("%02x", b[i]); printf("\n");
}

int main() {
    uint8_t Hb[16] = {0xc6,0xa1,0x3b,0x37,0x87,0x8f,0x5b,0x82,0x6f,0x4f,0x81,0x62,0xa1,0xc8,0xd8,0x79};
    uint8_t Xb[16]; for (int i=0;i<16;i++) Xb[i]=i;
    printf("expect       0dee47360a9b69d99ab5d81654439e03\n");
    __m128i H = bitrev128(_mm_loadu_si128((const __m128i*)Hb));
    __m128i X = bitrev128(_mm_loadu_si128((const __m128i*)Xb));
    __m128i Y = gfmul(X, H);
    phex("result", bitrev128(Y));

    /* multi-block: GHASH of two blocks should match chaining */
    uint8_t b2[32];
    for (int i=0;i<32;i++) b2[i]=i;
    __m128i y = _mm_setzero_si128();
    y = gfmul(_mm_xor_si128(y, bitrev128(_mm_loadu_si128((const __m128i*)b2))), H);
    y = gfmul(_mm_xor_si128(y, bitrev128(_mm_loadu_si128((const __m128i*)(b2+16)))), H);
    phex("two", bitrev128(y));
    return 0;
}
