#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

/* From OpenSSL crypto/modes/asm/aesni-gcm-x86_64.pl / ghash-x86_64.pl:
   void gcm_init_clmul(u128 Htable[16], const u64 Xi[2]);
   void gcm_ghash_clmul(u64 Xi[2], const u128 Htable[16], const u8 *inp, size_t len);
   len is in bytes and must be a multiple of 16.
   Xi and H are in "GHASH byte order" i.e. byte-swapped relative to NIST? 
   gcm_init_clmul reads H from rsi and byte-swaps internally (pshufd 0x4e is half swap, 
   plus the psllq is the carry-less left shift for reflected form).
   The caller (gcm128.c) passes H as the raw AES output (NIST order) after a BSWAP.
   We'll try both and compare against a known tag via full GCM later.
*/
extern void gcm_init_clmul(unsigned char Htable[256], const unsigned char Xi[16]);
extern void gcm_ghash_clmul(unsigned char Xi[16], const unsigned char Htable[256],
                            const unsigned char *inp, size_t len);
extern void gcm_init_avx(unsigned char Htable[256], const unsigned char Xi[16]);
extern void gcm_ghash_avx(unsigned char Xi[16], const unsigned char Htable[256],
                          const unsigned char *inp, size_t len);

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    const size_t N = 60000ull * 1024;
    unsigned char *data = malloc(N);
    memset(data, 0xab, N);
    unsigned char H[16];
    for (int i = 0; i < 16; i++) H[i] = i + 1;
    unsigned char Htable[512];
    memset(Htable, 0, sizeof(Htable));
    gcm_init_clmul(Htable, H);

    unsigned char Xi[16];
    memset(Xi, 0, 16);
    /* warmup */
    gcm_ghash_clmul(Xi, Htable, data, N);
    int reps = 3;
    double t0 = now();
    for (int i = 0; i < reps; i++) {
        memset(Xi, 0, 16);
        gcm_ghash_clmul(Xi, Htable, data, N);
    }
    double t1 = now();
    printf("ghash_clmul %.4f s  %.1f MB/s  xi=%02x%02x%02x%02x\n",
           (t1-t0)/reps, (N/1e6)/((t1-t0)/reps), Xi[0], Xi[1], Xi[2], Xi[3]);

    memset(Htable, 0, sizeof(Htable));
    gcm_init_avx(Htable, H);
    memset(Xi, 0, 16);
    gcm_ghash_avx(Xi, Htable, data, 64); /* warmup small */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        memset(Xi, 0, 16);
        gcm_ghash_avx(Xi, Htable, data, N);
    }
    t1 = now();
    printf("ghash_avx   %.4f s  %.1f MB/s  xi=%02x%02x%02x%02x\n",
           (t1-t0)/reps, (N/1e6)/((t1-t0)/reps), Xi[0], Xi[1], Xi[2], Xi[3]);
    free(data);
    return 0;
}
