int aes_gcm_encrypt(const uint8_t *key, int key_len,
                    const uint8_t *nonce, int nonce_len,
                    const uint8_t *aad, int aad_len,
                    const uint8_t *pt, int pt_len,
                    uint8_t *ct, uint8_t *tag) {
