    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) ok = 0;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, nonce_len, NULL) != 1) ok = 0;
    if (ok && EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce) != 1) ok = 0;
    if (ok && aad && aad_len > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, aad, aad_len) != 1) ok = 0;
    }
    if (ok && pt_len > 0) {
        if (EVP_EncryptUpdate(ctx, ct, &outlen, pt, pt_len) != 1) ok = 0;
    } else {
        outlen = 0;
    }
    if (ok && EVP_EncryptFinal_ex(ctx, ct + outlen, &outlen) != 1) ok = 0;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) != 1) ok = 0;
    EVP_CIPHER_CTX_free(ctx);
    return ok ? 0 : -1;
}
